// KagiCyber browser collector. Generated by scripts/build-collector.mjs from the CLI rule lists.
// Run once with the browser's JavaScript tool BEFORE touching the cookie banner. Passive: same-origin GETs
// the CLI would also make, plus public DNS over HTTPS. Secrets are masked. Returns one JSON string.
(async () => {
  const D = /* @data */ {};
  const t0 = performance.now(), d = document, host = location.hostname, origin = location.origin;
  const clip = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);
  const same = (u) => { try { return new URL(u, location.href).origin === origin; } catch { return false; } };
  const abs = (u, b) => { try { return new URL(u, b || location.href).href; } catch { return null; } };
  const get = async (u, max = 400000) => {
    const ac = new AbortController(); const tm = setTimeout(() => ac.abort(), 12000);
    try { const r = await fetch(u, { credentials: 'omit', cache: 'no-store', signal: ac.signal }); return { s: r.status, u: r.url, h: Object.fromEntries(r.headers), b: (await r.text()).slice(0, max) }; }
    catch (e) { return { s: 0, e: clip(e.message, 60), h: {}, b: '' }; } finally { clearTimeout(tm); }
  };
  const text = (html) => { const x = new DOMParser().parseFromString(html, 'text/html'); x.querySelectorAll('script,style,noscript,template,svg').forEach((n) => n.remove());
    const w = x.createTreeWalker(x.body || x, NodeFilter.SHOW_TEXT); const parts = []; while (w.nextNode()) parts.push(w.currentNode.nodeValue); return clip(parts.join(' '), 1e6); };
  const words = (t) => (t.match(/[\p{L}\p{N}]{2,}/gu) || []).length;
  // Same rule as maskSecret in the CLI: short values show only 2 characters.
  const mask = (v) => (v.length <= 12 ? `${v.slice(0, 2)}...(len ${v.length})` : `${v.slice(0, 4)}...${v.slice(-4)} (len ${v.length})`);
  const meta = (s) => d.querySelector(s)?.getAttribute('content') ?? null;
  const res = performance.getEntriesByType('resource').map((e) => e.name);
  const nav = performance.getEntriesByType('navigation')[0] || {};
  const o = { v: D.v, url: location.href, at: new Date().toISOString() };

  const home = await get(location.href);
  const rendered = clip(d.body?.innerText, 1e6);
  o.home = { status: home.s, headers: home.h, ttfb: nav.responseStart ? Math.round(nav.responseStart - nav.requestStart) : null, htmlBytes: home.b.length, wordsHtml: words(text(home.b)), wordsRendered: words(rendered), text: clip(rendered, 5000) };

  const hs = [...d.querySelectorAll('h1,h2,h3,h4,h5,h6')].map((h) => +h.tagName[1]);
  const im = [...d.images];
  const ld = [...d.querySelectorAll('script[type="application/ld+json"]')].map((s) => { try { const j = JSON.parse(s.textContent); return [j, ...(j['@graph'] || [])].flat().filter((x) => x?.['@type']).map((x) => ({ t: [].concat(x['@type']).join(), sameAs: [].concat(x.sameAs || []).length, address: !!x.address, logo: !!x.logo })); } catch { return [{ invalid: true }]; } }).flat();
  o.seo = { lang: d.documentElement.lang || null, title: d.title, description: meta('meta[name="description" i]'), robots: meta('meta[name="robots" i]'), canonical: d.querySelector('link[rel="canonical"]')?.href || null,
    hreflang: [...d.querySelectorAll('link[rel="alternate"][hreflang]')].map((l) => l.hreflang), og: !!meta('meta[property="og:title"]') && !!meta('meta[property="og:image"]'), twitter: !!meta('meta[name="twitter:card" i]'),
    viewport: meta('meta[name="viewport" i]'), charset: d.characterSet, doctype: !!d.doctype, favicon: !!d.querySelector('link[rel~="icon"]'), h1: hs.filter((h) => h === 1).length, skipped: hs.some((h, i) => i && h - hs[i - 1] > 1),
    img: { n: im.length, noAlt: im.filter((i) => !i.hasAttribute('alt')).length, noDim: im.filter((i) => !i.getAttribute('width') || !i.getAttribute('height')).length, modern: im.filter((i) => /\.(webp|avif)/i.test(i.currentSrc)).length },
    jsonLd: ld, blocking: [...d.head.querySelectorAll('script[src]')].filter((s) => !s.async && !s.defer && s.type !== 'module').length };

  const links = [...d.querySelectorAll('a[href]')].map((a) => [clip(a.innerText || a.getAttribute('aria-label'), 50), abs(a.getAttribute('href'))]).filter((l) => l[1] && !/^(mailto|tel|javascript):/.test(l[1]));
  const legalRe = D.legalRe;
  const legal = links.filter(([t, h]) => legalRe.test(`${t} ${decodeURIComponent(h)}`)).filter((l, i, a) => a.findIndex((x) => x[1] === l[1]) === i).slice(0, 12);
  o.links = { total: links.length, legal, tokenInUrl: links.filter((l) => /[?&](token|session|sid|auth|key)=/i.test(l[1])).length };
  o.forms = [...d.forms].map((f) => { const html = f.outerHTML; const fl = [...f.querySelectorAll('input,textarea,select')].filter((i) => !['hidden', 'submit', 'button'].includes(i.type));
    return { action: clip(f.getAttribute('action'), 100), fields: fl.length, password: !!f.querySelector('[type=password]'), unlabeled: fl.filter((i) => !(i.labels?.length || i.ariaLabel || i.placeholder)).length,
      near: clip(`${f.innerText} ${f.parentElement?.innerText || ''}`, 300), captcha: D.captcha.some((m) => html.includes(m)), processor: D.forms.find(([, r]) => r.test(html))?.[0] || null }; });
  o.embeds = [...d.querySelectorAll('iframe[src]')].map((f) => clip(f.src, 100)).filter((s) => !same(s));
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0 && getComputedStyle(e).visibility !== 'hidden'; };
  o.buttons = [...new Set([...d.querySelectorAll('button,[role=button],a.button,a[class*=btn],input[type=button],input[type=submit]')].filter(vis).map((b) => clip(b.innerText || b.value || b.ariaLabel, 40)).filter(Boolean))].slice(0, 40);

  const tp = {};
  for (const u of res) { try { const h = new URL(u).hostname; if (h !== host && !h.endsWith(host.replace(/^www\./, ''))) tp[h] = (tp[h] || 0) + 1; } catch {} }
  const cookies = d.cookie.split(';').map((c) => c.trim().split('=')[0]).filter(Boolean);
  o.before = { cookies, trackerCookies: cookies.filter((c) => D.tcookies.some((r) => r.test(c))), trackers: D.trackers.filter(([h]) => res.some((u) => u.includes(h))).map(([, n]) => n).filter((n, i, a) => a.indexOf(n) === i),
    thirdParty: Object.entries(tp).sort((a, b) => b[1] - a[1]).slice(0, 25).map(([h, n]) => `${h} ${n}`), storage: (() => { try { return Object.keys(localStorage).slice(0, 25); } catch { return []; } })(),
    priorConsent: cookies.filter((c) => /consent|cookieyes|cmplz|optanon|cc_cookie|didomi|borlabs|euconsent/i.test(c)) };

  const su = [...new Set([...d.scripts].map((s) => s.src).concat(res.filter((u) => /\.m?js(\?|$)/.test(u))).filter((s) => s && same(s)))].slice(0, 30);
  const bs = await Promise.all(su.map(async (u) => ({ u, r: await get(u, 3e6) })));
  const corpus = [['HTML', `${home.b}\n${[...d.scripts].filter((s) => !s.src).map((s) => s.textContent).join('\n')}`], ...bs.filter((b) => b.r.s === 200).map((b) => [new URL(b.u).pathname, b.r.b])];
  const secrets = [], seen = new Set();
  for (const [where, t] of corpus) { const lo = t.toLowerCase();
    for (const [name, sev, r, kw] of D.secrets) { if (kw.length && !kw.some((k) => lo.includes(k))) continue;
      for (const m of t.matchAll(new RegExp(r.source, r.flags.includes('g') ? r.flags : r.flags + 'g'))) { const v = m[1] || m[0];
        if (seen.has(v) || /x{6,}|your_|example|placeholder|dummy|<|\$\{/i.test(v) || /kagicyber-ignore/.test(t.slice(m.index, t.indexOf('\n', m.index)))) continue;
        seen.add(v); if (secrets.length < 25) secrets.push([name, sev, mask(v), where]); } } }
  const all = corpus.map((c) => c[1]).join('\n'), lo = all.toLowerCase();
  const maps = [...new Set(bs.map((b) => { const m = b.r.b.match(/\/\/# sourceMappingURL=(\S+)\s*$/); return m && !m[1].startsWith('data:') ? abs(m[1], b.u) : null; }).filter(Boolean))].slice(0, 3);
  o.code = { files: su.length, bytes: bs.reduce((n, b) => n + b.r.b.length, 0), gzipMissing: bs.filter((b) => b.r.b.length > 20000 && !b.r.h['content-encoding']).length, noCache: bs.filter((b) => !/max-age=[1-9]|immutable/.test(b.r.h['cache-control'] || '')).length,
    secrets, injected: D.trackers.filter(([h]) => lo.includes(h)).map(([, n]) => n).filter((n, i, a) => a.indexOf(n) === i), cmps: D.cmps.filter(([, ms]) => ms.some((m) => all.includes(m))).map(([n]) => n),
    consentModeDenied: /['"]consent['"]\s*,\s*['"]default['"][\s\S]{0,200}denied/.test(all), processors: D.forms.filter(([, r]) => r.test(all)).map(([n]) => n),
    staging: [...new Set(all.match(/https?:\/\/[\w.-]*(staging|stage|\.dev\.|test\.|internal|localhost:\d+)[\w.-]*/gi) || [])].slice(0, 5), libs: [...new Set(all.match(/jQuery v?\d+\.\d+\.\d+|AngularJS v\d[\d.]+|Bootstrap v\d[\d.]+|Vue\.js v\d[\d.]+|lodash \d[\d.]+/g) || [])].slice(0, 6),
    compromised: D.bad.filter((h) => res.some((u) => u.includes(h))), noSri: [...d.scripts].filter((s) => s.src && !same(s.src) && !s.integrity).length,
    sourceMaps: await Promise.all(maps.map(async (u) => [new URL(u).pathname, (await get(u, 100)).s])),
    bundleText: clip((all.match(/["'`]([^"'`\n]{25,300})["'`]/g) || []).filter((s) => /[a-ząćęłńóśźżäöüéè]{4,} [a-ząćęłńóśźżäöüéè]{3,}/i.test(s) && !/function|return|=>|\{|\}/.test(s)).join(' | '), 6000) };

  o.pages = Object.fromEntries(await Promise.all(legal.filter((l) => same(l[1])).slice(0, 6).map(async ([t, u]) => { const r = await get(u); const x = text(r.b);
    return [new URL(u).pathname, { link: t, status: r.s, words: words(x), garbled: (x.match(/Ã[\x80-\xbf¡-¿]|Ä[™\x80-\xbf]|Ĺ[›‚ş]|â€/g) || []).length, text: clip(x, 9000) }]; })));

  const wk = async (p, n = 4000) => { const r = await get(origin + p, n); return [r.s, r.s === 200 && !/<html/i.test(r.b.slice(0, 300)) ? r.b : '']; };
  const [rb, st, lt, nf] = await Promise.all([wk('/robots.txt', 8000), wk('/.well-known/security.txt', 1500), wk('/llms.txt', 800), wk(`/kc-${Math.random().toString(36).slice(2, 9)}`, 100)]);
  const smu = (rb[1].match(/^\s*sitemap:\s*(\S+)/im) || [])[1] || origin + '/sitemap.xml';
  const sm = same(smu) ? await get(smu, 3e5) : { s: 0, b: '' };
  o.files = { robots: rb, securityTxt: st, llmsTxt: lt, notFound: nf[0], sitemap: { url: smu, status: sm.s, valid: /<(urlset|sitemapindex)/i.test(sm.b), urls: (sm.b.match(/<loc>/g) || []).length, lastmod: /<lastmod>/i.test(sm.b) } };
  const il = [...new Set(links.map((l) => l[1].split('#')[0]).filter((u) => same(u) && u !== location.href))].slice(0, 8);
  o.linkCheck = await Promise.all(il.map(async (u) => [new URL(u).pathname, (await get(u, 50)).s]));

  const dns = async (n, t) => { try { const j = await (await fetch(`https://dns.google/resolve?name=${n}&type=${t}`, { credentials: 'omit' })).json(); return (j.Answer || []).map((a) => String(a.data).replace(/"/g, '')); } catch { return null; } };
  const ap = host.replace(/^www\./, '');
  const [tx, dm, ca, mx] = await Promise.all([dns(ap, 'TXT'), dns('_dmarc.' + ap, 'TXT'), dns(ap, 'CAA'), dns(ap, 'MX')]);
  o.dns = tx === null ? 'not run (blocked by the page)' : { spf: tx.filter((t) => /^v=spf1/i.test(t)), dmarc: (dm || []).filter((t) => /^v=DMARC1/i.test(t)), caa: (ca || []).length, mx: (mx || []).length };
  o.ms = Math.round(performance.now() - t0);
  return JSON.stringify(o);
})();
